const b = $input.first().json.body;

const ils = n => '₪' + Number(n || 0).toLocaleString('en-US');
const date = d => d ? d.split('-').reverse().join('/') : '';
const line = '━━━━━━━━━━━━━━━━';
const L = [];

L.push(`🧾 הזמנה חדשה #${b.order.orderNumber}`);
L.push(`📅 תאריך: ${date(b.order.orderDate)}${b.order.agentName ? ' | 👤 סוכן: ' + b.order.agentName : ''}`);

const c = b.customer, a = c.address || {};
L.push('', line, '👤 פרטי לקוח');
L.push(`שם: ${c.fullName}`);
if (c.businessName) L.push(`עסק: ${c.businessName}`);
if (c.idNumber) L.push(`ת.ז/ח.פ: ${c.idNumber}`);
L.push(`טלפון: ${[c.phone, c.phone2].filter(Boolean).join(' / ')}`);
if (c.email) L.push(`אימייל: ${c.email}`);
L.push(`כתובת: ${[[a.street, a.houseNumber].filter(Boolean).join(' '), a.floor ? 'קומה ' + a.floor : null, a.city].filter(Boolean).join(', ')}`);

L.push('', line, '📦 פריטים');
(b.items || []).forEach((i, idx) => {
  if (idx > 0) L.push('');
  L.push(`${i.line}. ${i.product}${i.quantity > 1 ? ` (× ${i.quantity})` : ''}`);
  if (i.description) L.push(`   📝 ${i.description}`);

  // formVersion 3 — label-resolved spec lines (מפרט המוצר)
  (i.specLines || []).forEach(s => L.push(`   ${s.label}: ${s.value}`));

  // מפתחים (מערכות זכוכית נאספות)
  (i.openings || []).forEach(o => {
    const size = [o.widthMm, o.heightMm].filter(Boolean).join('×');
    const parts = [size ? size + ' מ״מ' : null, o.opening].filter(Boolean).join(' — ');
    L.push(`   מפתח ${o.index}: ${parts}`);
  });

  // legacy fields — only free-text ("אחר") products fill these
  const d = i.dimensionsCm || {};
  const dims = [
    d.length ? `אורך ${d.length}` : null,
    d.projection ? `יציאה ${d.projection}` : null,
    d.height ? `גובה ${d.height}` : null,
    d.installationHeight ? `גובה התקנה ${d.installationHeight}` : null
  ].filter(Boolean).join(' × ');
  if (dims) L.push(`   מידות: ${dims} ס"מ`);
  if (i.frameColor) L.push(`   צבע: ${i.frameColor}`);
  if (i.cover) L.push(`   כיסוי: ${i.cover}${i.coverColor ? ' (' + i.coverColor + ')' : ''}`);
  if (i.opening) L.push(`   פתיחה: ${i.opening}`);
  if (i.finish) L.push(`   גימור: ${i.finish}`);

  // תוספות
  (i.addons || []).forEach(ad => {
    const det = [
      ad.qty ? '× ' + ad.qty : null,
      ad.widthMm ? 'רוחב ' + ad.widthMm + ' מ״מ' : null,
      ad.heightMm ? 'גובה ' + ad.heightMm + ' מ״מ' : null,
      ad.lengthM ? ad.lengthM + ' מטר רץ' : null,
      ad.spotCount ? ad.spotCount + ' ספוטים' : null,
      ad.option,
      ad.note
    ].filter(Boolean).join(', ');
    L.push(`   ➕ ${ad.name}${det ? ' — ' + det : ''}${ad.priceIls ? ' — ' + ils(ad.priceIls) : ''}`);
    (ad.entries || []).forEach(e => {
      L.push(`      מערכת ${e.systemNumber || ''}${e.priceIls ? ' — ' + ils(e.priceIls) : ''}`);
    });
  });

  if (i.priceIls) L.push(`   מחיר יחידה: ${ils(i.priceIls)}`);
  if (i.lineTotalIls) L.push(`   סה"כ לסעיף: ${ils(i.lineTotalIls)}`);
  if (i.locationImage) L.push('   📷 צורפה תמונת מיקום המערכת');
});

const t = b.totals || {};
L.push('', line, '💰 סיכום כספי');
L.push(`סה"כ הזמנה (לפני מע"מ): ${ils(t.itemsTotal)}`);
L.push(`שולם: ${ils(t.paymentsTotal)}`);
L.push(`יתרה לתשלום: ${ils((t.itemsTotal || 0) - (t.paymentsTotal || 0))}`);

if ((b.payments || []).length) {
  L.push('', '💳 תשלומים שהתקבלו');
  b.payments.forEach(p => {
    const det = [p.bank, p.checkNumber ? "שיק מס' " + p.checkNumber : null, p.date ? date(p.date) : null].filter(Boolean).join(', ');
    L.push(`${p.line}. ${p.methodLabel || p.method}${det ? ' — ' + det : ''} — ${ils(p.amountIls)}`);
  });
}

const tr = b.terms || {};
if ((tr.paymentSchedule || []).length) {
  L.push('', line, '📆 פריסת תשלומים');
  tr.paymentSchedule.forEach(p => {
    const parts = [p.percent ? p.percent + '%' : null, p.amountIls ? ils(p.amountIls) : null].filter(Boolean).join(', ');
    L.push(`תשלום ${p.line} — ${p.milestoneLabel}${parts ? ': ' + parts : ''}`);
  });
}
if (tr.measurementLeadTimeDays) {
  L.push('', `⏱️ אספקה: עד ${tr.measurementLeadTimeDays} ימי עבודה מהתשלום או מהמדידה הסופית (המוקדם מביניהם)`);
}

if (b.signature && b.signature.dataUrl) L.push('', '✍️ חתימת לקוח מצורפת');

const text = L.join('\n');
const html = '<div dir="rtl" style="text-align:right">' +
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>') +
  '</div>';

return [{ json: { mondayItemId: b.customer.mondayItemId, orderNumber: b.order.orderNumber, text, html } }];
